func newLogPipeline(t *testing.T) *logPipeline {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 20*time.Second)
	t.Cleanup(cancel)
	conn := startNATS(t)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	stream, err := OpenStream(ctx, js, "gru", 1)
	if err != nil {
		t.Fatal(err)
	}
	p := &logPipeline{ctx: ctx, conn: conn, js: js, stream: stream, key: publicUserKey(t), barriers: NewCounter("gru", "barrier")}
	p.follow(t, NewView("gru"))
	return p
}

func (p *logPipeline) follow(t *testing.T, view *View) {
	t.Helper()
	p.view = view
	ctx, cancel := context.WithCancel(p.ctx)
	p.stop = cancel
	done := make(chan struct{})
	p.done = done
	go func() {
		defer close(done)
		p.stream.Follow(ctx, view, func(_ context.Context, node, key string) bool {
			return key == p.key && (strings.HasPrefix(node, "node-") || node == "barrier")
		})
	}()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(3 * time.Second):
			t.Error("log follower did not stop")
		}
	})
	p.http = httptest.NewServer(Handler(view))
	p.http.Client().Timeout = 2 * time.Second
	t.Cleanup(p.http.Close)
}

func (p *logPipeline) publish(t *testing.T, key string, window Window) Window {
	t.Helper()
	data, err := json.Marshal(window)
	if err != nil {
		t.Fatal(err)
	}
	ack, err := p.js.Publish(p.ctx, protocol.AgentObservation("gru", key, "logs"), data)
	if err != nil {
		t.Fatal(err)
	}
	stored, err := p.stream.stream.GetMsg(p.ctx, ack.Sequence)
	if err != nil {
		t.Fatal(err)
	}
	var observed Window
	if err := json.Unmarshal(stored.Data, &observed); err != nil {
		t.Fatal(err)
	}
	return observed
}

func (p *logPipeline) get(t *testing.T, query string) Reply {
	t.Helper()
	req, err := http.NewRequestWithContext(p.ctx, http.MethodGet, p.http.URL+"/v1/logs?"+query, nil)
	if err != nil {
		t.Fatal(err)
	}
	response, err := p.http.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	data, err := io.ReadAll(io.LimitReader(response.Body, 2<<20))
	if err != nil {
		t.Fatal(err)
	}
	if response.StatusCode != http.StatusOK {
		t.Fatalf("log HTTP status %d: %s", response.StatusCode, data)
	}
	if response.Header.Get("Content-Type") != "application/json" || response.Header.Get("Cache-Control") != "no-store" {
		t.Fatalf("log response headers: %v", response.Header)
	}
	var reply Reply
	if err := json.Unmarshal(data, &reply); err != nil {
		t.Fatal(err)
	}
	return reply
}

// A streamed barrier proves earlier messages were processed before HTTP assertions.
func (p *logPipeline) sync(t *testing.T) {
	t.Helper()
	p.barriers.Add(Record{Service: "barrier", Level: LevelDebug, Message: "observed"})
	p.publish(t, p.key, p.barriers.Flush(time.Now().UTC().Truncate(time.Minute)))
	p.barrierCount++
	tick := time.NewTicker(5 * time.Millisecond)
	defer tick.Stop()
	for {
		reply := p.get(t, "service=barrier")
		if len(reply.Classes) == 1 && reply.Classes[0].Count == p.barrierCount {
			return
		}
		select {
		case <-p.ctx.Done():
			t.Fatalf("log stream barrier: %v; reply=%+v", p.ctx.Err(), reply)
		case <-tick.C:
		}
	}
}

func (p *logPipeline) query(t *testing.T, query string) Reply {
	t.Helper()
	p.sync(t)
	reply := p.get(t, query)
	reply.Classes = slices.DeleteFunc(reply.Classes, func(c ReplyClass) bool { return c.Service == "barrier" })
	reply.Totals = slices.DeleteFunc(reply.Totals, func(c Total) bool { return c.Service == "barrier" })
	return reply
}

func startNATS(t *testing.T) *nats.Conn {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true,
		StoreDir: t.TempDir(), NoLog: true, NoSigs: true})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	return conn
}

func publicUserKey(t *testing.T) string {
	t.Helper()
	pair, err := nkeys.CreateUser()
	if err != nil {
		t.Fatal(err)
	}
	public, err := pair.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	return public
}

func OpenStream(ctx context.Context, js jetstream.JetStream, cell string, replicas int) (*Stream, error) {
	if js == nil {
		return nil, errors.New("log summary stream requires JetStream")
	}
	subject := protocol.AgentObservation(cell, "*", "logs")
	if subject == "" {
		return nil, errors.New("log summary subject is invalid")
	}
	config := jetstream.StreamConfig{
		Name:        StreamName,
		Description: "Regional log summary windows",
		Subjects:    []string{subject},
		Storage:     jetstream.FileStorage,
		Replicas:    replicas,
		Retention:   jetstream.LimitsPolicy,
		Discard:     jetstream.DiscardOld,
		MaxAge:      streamMaxAge,
		MaxBytes:    streamBytes,
		MaxMsgs:     -1,
		MaxMsgSize:  maxMessageBytes,
	}
	stream, err := js.CreateStream(ctx, config)
	if errors.Is(err, jetstream.ErrStreamNameAlreadyInUse) {
		stream, err = js.UpdateStream(ctx, config)
	}
	if err != nil {
		return nil, fmt.Errorf("open log summary stream: %w", err)
	}
	return &Stream{stream: stream}, nil
}

func (stream *Stream) Follow(ctx context.Context, view *View, verify func(ctx context.Context, node, nkey string) bool) {
	verdicts := &verdictCache{verify: verify, verdicts: make(map[nodeKey]verdict)}
	delay := retryFirst
	failing := false
	for {
		ctx := observability.StartTrace(ctx)
		started := time.Now()
		ready, err := stream.run(ctx, view, verdicts)
		if ready && failing {
			slog.InfoContext(ctx, "log summary follower recovered", observability.ComponentKey, "logs")
			failing = false
		}
		if ctx.Err() != nil {
			return
		}
		if failing {
			slog.DebugContext(ctx, "log summary follower still failing", observability.ComponentKey, "logs", "error", err)
		} else {
			slog.WarnContext(ctx, "log summary follower failed; retrying", observability.ComponentKey, "logs", "error", err)
			failing = true
		}
		// A consumer that lasted a while was healthy: its next failure starts over.
		if time.Since(started) >= retryMax {
			delay = retryFirst
		}
		select {
		case <-ctx.Done():
			return
		case <-time.After(delay):
		}
		delay = min(2*delay, retryMax)
	}
}

// run follows the stream until the consumer fails or ctx ends. ready reports
// whether the consumer was created.
func (stream *Stream) run(ctx context.Context, view *View, verdicts *verdictCache) (bool, error) {
	start := time.Now().Add(-retention)
	consumer, err := stream.stream.OrderedConsumer(ctx, jetstream.OrderedConsumerConfig{
		DeliverPolicy: jetstream.DeliverByStartTimePolicy,
		OptStartTime:  &start,
	})
	if err != nil {
		return false, err
	}
	messages, err := consumer.Messages()
	if err != nil {
		return true, err
	}
	defer messages.Stop()
	stop := context.AfterFunc(ctx, messages.Stop)
	defer stop()
	for {
		msg, err := messages.Next()
		if err != nil {
			return true, err
		}
		accept(ctx, msg, view, verdicts)
	}
}

// accept counts one window whose node is verified for the NKey in its subject.
// A malformed or unverified window is dropped.
func accept(ctx context.Context, msg jetstream.Msg, view *View, verdicts *verdictCache) {
	var window Window
	if protocol.DecodeStrict(msg.Data(), &window, maxWindowBytes) != nil || window.Version != 1 {
		return
	}
	// The subject is ts.orch.v1.<cell>.agent.<nkey>.observation.logs.
	tokens := strings.Split(msg.Subject(), ".")
	if len(tokens) < 3 || !verdicts.allowed(ctx, window.Node, tokens[len(tokens)-3]) {
		return
	}
	view.Add(window, time.Now())
}

func (c *verdictCache) allowed(ctx context.Context, node, nkey string) bool {
	key := nodeKey{node, nkey}
	if v, ok := c.verdicts[key]; ok && time.Since(v.at) < verdictTTL {
		return v.ok
	}
	ok := c.verify(ctx, node, nkey)
	c.verdicts[key] = verdict{ok: ok, at: time.Now()}
	return ok
}

func Handler(view *View) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		params := request.URL.Query()
		req := Request{Version: 1, Window: cmp.Or(params.Get("window"), "1h"),
			MinLevel: cmp.Or(params.Get("min_level"), LevelDebug), Service: params.Get("service")}
		if params.Has("limit") {
			limit, err := strconv.Atoi(params.Get("limit"))
			if err != nil {
				http.Error(writer, "limit must be a number", http.StatusBadRequest)
				return
			}
			req.Limit = limit
		}
		if err := req.Validate(); err != nil {
			http.Error(writer, err.Error(), http.StatusBadRequest)
			return
		}
		writer.Header().Set("Content-Type", "application/json")
		writer.Header().Set("Cache-Control", "no-store")
		_ = json.NewEncoder(writer).Encode(view.Summary(req, time.Now()))
	})
}

func testClass(service, level, message string, count int) Class {
	return Class{Service: service, Level: level, Component: "core", Message: message, Count: count, Example: message + " example"}
}

func testWindow(node, boot string, seq uint64, minute time.Time, classes ...Class) Window {
	return Window{Version: 1, Region: "gru", Node: node, Minute: minute, Boot: boot, Seq: seq, Classes: classes}
}

// NewView returns an empty summary for region.
func NewView(region string) *View {
	return &View{region: region, classes: make(map[Class]*classStats), seqs: make(map[nodeBoot]seqState)}
}

// Add counts one node window at now. A window older than the retention, or one
// the view already counted, is ignored: a replay after a restart delivers both.
func (v *View) Add(w Window, now time.Time) {
	v.mu.Lock()
	defer v.mu.Unlock()
	if w.Minute.Before(now.Add(-retention)) || !v.track(w, now) {
		return
	}
	for _, c := range w.Classes {
		key := Class{Service: c.Service, Level: c.Level, Component: c.Component, Message: c.Message}
		stats, ok := v.classes[key]
		if !ok {
			stats = v.admit()
			v.classes[key] = stats
		}
		stats.add(w.Node, w.Minute, c)
	}
}

// track reports whether w is new within its boot and counts the sequence gap it reveals.
func (v *View) track(w Window, now time.Time) bool {
	if now.Sub(v.pruned) >= time.Hour {
		v.pruned = now
		for key, state := range v.seqs {
			if state.seen.Before(now.Add(-retention)) {
				delete(v.seqs, key)
			}
		}
	}
	key := nodeBoot{w.Node, w.Boot}
	last, seen := v.seqs[key]
	if seen && w.Seq <= last.seq {
		return false
	}
	if seen && w.Seq > last.seq+1 {
		v.gaps += int(w.Seq - last.seq - 1)
	}
	v.seqs[key] = seqState{seq: w.Seq, seen: now}
	return true
}

// admit makes room for a new class. A full region evicts the class seen least recently.
func (v *View) admit() *classStats {
	if len(v.classes) >= maxClassKeys {
		var oldest Class
		var oldestStats *classStats
		for key, stats := range v.classes {
			if oldestStats == nil || stats.last.Before(oldestStats.last) {
				oldest, oldestStats = key, stats
			}
		}
		delete(v.classes, oldest)
		v.evicted++
	}
	return &classStats{nodes: make(map[string]struct{})}
}

func (s *classStats) add(node string, minute time.Time, c Class) {
	if s.first.IsZero() || minute.Before(s.first) {
		s.first = minute
	}
	if !minute.Before(s.last) {
		s.last, s.example = minute, c.Example
	}
	if len(s.nodes) < maxNodesPerClass {
		s.nodes[node] = struct{}{}
	}
	addBucket(s.minutes[:], minute.Unix()/60, c.Count)
	addBucket(s.hours[:], minute.Unix()/3600, c.Count)
}

// count is the class's records in the window that ends at now.
func (s *classStats) count(window string, now time.Time) int {
	if window == "24h" {
		return sumBuckets(s.hours[:], now.Unix()/3600)
	}
	return sumBuckets(s.minutes[:], now.Unix()/60)
}

func (s *classStats) reply(class Class) ReplyClass {
	nodes := make([]string, 0, len(s.nodes))
	for node := range s.nodes {
		nodes = append(nodes, node)
	}
	slices.Sort(nodes)
	return ReplyClass{Service: class.Service, Level: class.Level, Component: class.Component, Message: class.Message,
		Count: class.Count, Nodes: nodes, First: s.first, Last: s.last, Example: s.example}
}

// addBucket counts into its period's slot. A period older than the slot's is
// outside the ring, so its count is dropped.
func addBucket(slots []bucket, period int64, count int) {
	slot := &slots[period%int64(len(slots))]
	if slot.period < period {
		*slot = bucket{period: period}
	}
	if slot.period == period {
		slot.count += count
	}
}

// sumBuckets totals the periods of the ring that end at now.
func sumBuckets(slots []bucket, now int64) int {
	total := 0
	for _, slot := range slots {
		if slot.period > now-int64(len(slots)) && slot.period <= now {
			total += slot.count
		}
	}
	return total
}

// Validate reports whether the query serves the request.
func (r Request) Validate() error {
	switch {
	case r.Version != 1:
		return errors.New("version must be 1")
	case r.Window != "1h" && r.Window != "24h":
		return errors.New("window must be 1h or 24h")
	case !validLevel(r.MinLevel):
		return errors.New("min_level must be DEBUG, INFO, WARN or ERROR")
	case r.Limit < 0 || r.Limit > maxLimit:
		return errors.New("limit must be from 0 to 500")
	case len(r.Service) > maxServiceBytes:
		return errors.New("service must be at most 64 bytes")
	}
	return nil
}

func (r Request) keeps(class Class) bool {
	return severity(class.Level) >= severity(r.MinLevel) && (r.Service == "" || class.Service == r.Service)
}

// Summary answers req as of now. Totals cover every matching class; the classes
// are the most frequent up to the limit.
func (v *View) Summary(req Request, now time.Time) Reply {
	v.mu.Lock()
	defer v.mu.Unlock()
	reply := Reply{Version: 1, Region: v.region, From: windowStart(req.Window, now), To: now.UTC(), Gaps: v.gaps,
		Totals: []Total{}, Classes: []ReplyClass{}}
	totals := make(map[[2]string]int)
	var hits []hit
	for key, stats := range v.classes {
		if !req.keeps(key) {
			continue
		}
		count := stats.count(req.Window, now)
		if count == 0 {
			continue
		}
		key.Count = count
		totals[[2]string{key.Service, key.Level}] += count
		hits = append(hits, hit{key, stats})
	}
	for pair, count := range totals {
		reply.Totals = append(reply.Totals, Total{Service: pair[0], Level: pair[1], Count: count})
	}
	slices.SortFunc(reply.Totals, compareTotals)
	slices.SortFunc(hits, func(a, b hit) int { return compareClasses(a.Class, b.Class) })
	limit := min(cmp.Or(req.Limit, defaultLimit), maxLimit)
	if len(hits) > limit {
		hits = hits[:limit]
		reply.Truncated = true
	}
	for _, h := range hits {
		reply.Classes = append(reply.Classes, h.stats.reply(h.Class))
	}
	return reply
}

// Errors returns the most frequent WARN and ERROR classes of the last hour, for
// the global rollup. It does no I/O.
func (v *View) Errors(limit int, now time.Time) []ReplyClass {
	return v.Summary(Request{Version: 1, Window: "1h", MinLevel: LevelWarn, Limit: limit}, now).Classes
}

// windowStart is the first instant of the window: 59 minutes back for "1h", 23 hours back for "24h".
func windowStart(window string, now time.Time) time.Time {
	if window == "24h" {
		return now.Truncate(time.Hour).Add(-23 * time.Hour).UTC()
	}
	return now.Truncate(time.Minute).Add(-59 * time.Minute).UTC()
}

func compareTotals(a, b Total) int {
	return cmp.Or(cmp.Compare(a.Service, b.Service), cmp.Compare(severity(a.Level), severity(b.Level)))
}

func persistedWindow(t *testing.T, window Window) Window {
	t.Helper()
	p := newLogPipeline(t)
	return p.publish(t, p.key, window)
}

const (
	maxClasses     = 128
	maxWindowBytes = 64 << 10
)

// Window is one node's records for one minute, the JSON the host agent publishes.
type Window struct {
	Version int       `json:"v"`
	Region  string    `json:"region"`
	Node    string    `json:"node"`
	Minute  time.Time `json:"minute"`
	Boot    string    `json:"boot"`
	Seq     uint64    `json:"seq"`
	Classes []Class   `json:"classes"`
	Dropped int       `json:"dropped"`
}

// Class is one message class in a window, with its records in the minute.
type Class struct {
	Service   string `json:"service"`
	Level     string `json:"level"`
	Component string `json:"component"`
	Message   string `json:"message"`
	Count     int    `json:"count"`
	Example   string `json:"example"`
}

func NewCounter(region, node string) *Counter {
	return &Counter{region: region, node: node, boot: entityid.New(), classes: make(map[Class]tally)}
}

// Add counts one record in the minute being counted. A class keeps the example of its first record.
func (c *Counter) Add(r Record) {
	key := Class{Service: r.Service, Level: r.Level, Component: r.Component, Message: r.Message}
	t, seen := c.classes[key]
	if !seen {
		t.example = r.Example
	}
	t.count++
	c.classes[key] = t
}

// Flush ends a minute and returns its window. The window keeps the most frequent
// classes and counts the rest as dropped; the counter starts the next minute empty.
func (c *Counter) Flush(minute time.Time) Window {
	classes := make([]Class, 0, len(c.classes))
	for key, t := range c.classes {
		key.Count, key.Example = t.count, t.example
		classes = append(classes, key)
	}
	clear(c.classes)
	slices.SortFunc(classes, compareClasses)
	window := Window{Version: 1, Region: c.region, Node: c.node, Minute: minute.UTC(), Boot: c.boot, Seq: c.seq, Classes: classes}
	c.seq++
	if len(classes) > maxClasses {
		window.Dropped = sumCounts(classes[maxClasses:])
		window.Classes = classes[:maxClasses]
	}
	for encodedLen(window) > maxWindowBytes {
		last := len(window.Classes) - 1
		window.Dropped += window.Classes[last].Count
		window.Classes = window.Classes[:last]
	}
	return window
}

// compareClasses puts the most frequent first. Ties go to the more severe level, then to text.
func compareClasses(a, b Class) int {
	return cmp.Or(cmp.Compare(b.Count, a.Count), cmp.Compare(severity(b.Level), severity(a.Level)),
		cmp.Compare(a.Service, b.Service), cmp.Compare(a.Component, b.Component), cmp.Compare(a.Message, b.Message))
}

func sumCounts(classes []Class) int {
	total := 0
	for _, class := range classes {
		total += class.Count
	}
	return total
}

// encodedLen is the window's JSON size. Marshal cannot fail: every field is a string or a number.
func encodedLen(window Window) int {
	data, _ := json.Marshal(window)
	return len(data)
}

var (
	entropy = ulid.Monotonic(rand.Reader, 0)
	mu      sync.Mutex
)

// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

func journalRecords(t *testing.T, entries ...Entry) []Record {
	t.Helper()
	p := newLogPipeline(t)
	path := filepath.Join(t.TempDir(), "journal.jsonl")
	file, err := os.Create(path)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		line, err := json.Marshal(map[string]string{"_SYSTEMD_UNIT": e.Unit, "_COMM": e.Comm, "_PID": e.PID, "PRIORITY": e.Priority, "__REALTIME_TIMESTAMP": fmt.Sprint(e.At.UnixMicro()), "MESSAGE": e.Message})
		if err != nil {
			t.Fatal(err)
		}
		if _, err := fmt.Fprintln(file, string(line)); err != nil {
			t.Fatal(err)
		}
	}
	for _, invalid := range []string{`[104,105]`, `--`, ``, `{"_COMM":"invalid","MESSAGE":[104,105]}`} {
		if _, err := fmt.Fprintln(file, invalid); err != nil {
			t.Fatal(err)
		}
	}
	if err := file.Close(); err != nil {
		t.Fatal(err)
	}
	file, err = os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	counter := NewCounter("gru", "node-a")
	var parser Parser
	scanner := bufio.NewScanner(file)
	line := 0
	for scanner.Scan() {
		entry, ok := DecodeJournal(scanner.Bytes())
		if line >= len(entries) {
			if ok {
				t.Fatalf("invalid journal line %q was accepted", scanner.Text())
			}
		} else {
			want := entries[line]
			if !ok || !entry.At.Equal(want.At.Truncate(time.Microsecond)) {
				t.Fatalf("journal entry %d timestamp = %v, decoded = %v", line, entry.At, ok)
			}
			entryFields, wantFields := entry, want
			entryFields.At, wantFields.At = time.Time{}, time.Time{}
			if entryFields != wantFields {
				t.Fatalf("journal entry %d = %+v, want %+v", line, entry, want)
			}
			if record, ok := parser.Parse(entry); ok {
				counter.Add(record)
			}
		}
		line++
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	for _, record := range parser.Flush() {
		counter.Add(record)
	}
	p.publish(t, p.key, counter.Flush(time.Now().UTC().Truncate(time.Minute)))
	reply := p.query(t, "limit=500")
	var records []Record
	for _, c := range reply.Classes {
		for range c.Count {
			records = append(records, Record{Service: c.Service, Level: c.Level, Component: c.Component, Message: c.Message, Example: c.Example})
		}
	}
	return records
}

func DecodeJournal(line []byte) (Entry, bool) {
	var raw struct {
		Unit     string          `json:"_SYSTEMD_UNIT"`
		Comm     string          `json:"_COMM"`
		PID      string          `json:"_PID"`
		Priority string          `json:"PRIORITY"`
		Realtime string          `json:"__REALTIME_TIMESTAMP"`
		Message  json.RawMessage `json:"MESSAGE"`
	}
	if json.Unmarshal(line, &raw) != nil {
		return Entry{}, false
	}
	var message string
	if json.Unmarshal(raw.Message, &message) != nil {
		return Entry{}, false
	}
	entry := Entry{Unit: raw.Unit, Comm: raw.Comm, PID: raw.PID, Message: message, Priority: raw.Priority}
	if micros, err := strconv.ParseInt(raw.Realtime, 10, 64); err == nil {
		entry.At = time.UnixMicro(micros)
	}
	return entry, true
}

func validLevel(level string) bool {
	return severity(level) >= 0
}

func severity(level string) int {
	for i, known := range levels {
		if known == level {
			return i
		}
	}
	return -1
}

func (p *Parser) Parse(e Entry) (Record, bool) {
	p.queue = append(p.queue, p.step(e)...)
	if len(p.queue) == 0 {
		return Record{}, false
	}
	r := p.queue[0]
	p.queue = p.queue[1:]
	return r, true
}

// Flush returns the queued records and the headers whose message never came.
func (p *Parser) Flush() []Record {
	out := p.queue
	p.queue = nil
	for pid, head := range p.held {
		out = append(out, head)
		delete(p.held, pid)
	}
	return out
}

func (p *Parser) step(e Entry) []Record {
	var out []Record
	indented := strings.HasPrefix(e.Message, " ")
	if head, ok := p.held[e.PID]; ok {
		delete(p.held, e.PID)
		if indented {
			if p.inRecord == nil {
				p.inRecord = make(map[string]bool)
			}
			p.inRecord[e.PID] = true
			head.Message, head.Example = Normalize(e.Message), example(e.Message)
			return []Record{head}
		}
		out = append(out, head)
	}
	// Exception text and stack frames are indented too; they end with the record.
	if indented && p.inRecord[e.PID] {
		return out
	}
	delete(p.inRecord, e.PID)
	if head, ok := dotnetHeader(e); ok {
		if p.held == nil {
			p.held = make(map[string]Record)
		}
		p.held[e.PID] = head
		return out
	}
	if r, ok := Classify(e); ok {
		out = append(out, r)
	}
	return out
}

// Classify classifies an entry that is a whole record by itself. Any other
// line is a record too, at the level its journal PRIORITY gives.
func Classify(e Entry) (Record, bool) {
	if strings.TrimSpace(e.Message) == "" {
		return Record{}, false
	}
	for _, classify := range []func(Entry) (Record, bool){slogRecord, natsRecord, netbirdRecord} {
		if r, ok := classify(e); ok {
			return r, true
		}
	}
	return Record{Service: unitService(e), Level: priorityLevel(e.Priority), Message: Normalize(e.Message), Example: example(e.Message)}, true
}

// slogRecord reads record v1 and slog JSON: {"level","msg","component","error","service"}.
func slogRecord(e Entry) (Record, bool) {
	var slog struct {
		Level     string `json:"level"`
		Msg       string `json:"msg"`
		Component string `json:"component"`
		Error     string `json:"error"`
		Service   string `json:"service"`
	}
	if !strings.HasPrefix(e.Message, "{") || json.Unmarshal([]byte(e.Message), &slog) != nil || !validLevel(slog.Level) {
		return Record{}, false
	}
	message := slog.Msg
	if slog.Error != "" {
		message += ": " + slog.Error
	}
	return Record{Service: cmp.Or(slog.Service, unitService(e)), Level: slog.Level, Component: slog.Component,
		Message: Normalize(message), Example: example(e.Message)}, true
}

var (
	dotnetHeaderLine = regexp.MustCompile(`^(trce|dbug|info|warn|fail|crit): ([^\[ ]+)`)
	dotnetLevels     = map[string]string{"trce": LevelDebug, "dbug": LevelDebug, "info": LevelInfo, "warn": LevelWarn, "fail": LevelError, "crit": LevelError}
)

// dotnetHeader reads a .NET console header; its message follows on a later line.
func dotnetHeader(e Entry) (Record, bool) {
	m := dotnetHeaderLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	return Record{Service: commService(e), Level: dotnetLevels[m[1]], Component: m[2]}, true
}

var (
	natsLine   = regexp.MustCompile(`^\[\d+\] \[(INF|WRN|ERR|FTL|DBG|TRC)\] (.*)`)
	natsLevels = map[string]string{"TRC": LevelDebug, "DBG": LevelDebug, "INF": LevelInfo, "WRN": LevelWarn, "ERR": LevelError, "FTL": LevelError}
	// A permission violation names its client and account; one cause is one class.
	violationQuote   = regexp.MustCompile(`"[^"]*"`)
	violationAccount = regexp.MustCompile(`\b(account|JWT)\s+\S+`)
)

// natsRecord reads an embedded NATS server line: "[pid] [WRN] text".
func natsRecord(e Entry) (Record, bool) {
	m := natsLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	text := m[2]
	if strings.Contains(text, "Violation") {
		text = violationAccount.ReplaceAllString(violationQuote.ReplaceAllString(text, ""), "")
	}
	return Record{Service: "ts-orchestrator", Level: natsLevels[m[1]], Component: "nats", Message: Normalize(text), Example: example(e.Message)}, true
}

var (
	netbirdLine   = regexp.MustCompile(`^\S+ (TRAC|DEBU|INFO|WARN|ERRO|FATA|PANI) (?:\[[^\]]*\] )?(\S+?):\d+: (.*)$`)
	netbirdLevels = map[string]string{"TRAC": LevelDebug, "DEBU": LevelDebug, "INFO": LevelInfo, "WARN": LevelWarn, "ERRO": LevelError, "FATA": LevelError, "PANI": LevelError}
)

// netbirdRecord reads a NetBird client line: "time LEVEL [peer] file.go:line: text".
func netbirdRecord(e Entry) (Record, bool) {
	m := netbirdLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	return Record{Service: "netbird", Level: netbirdLevels[m[1]], Component: m[2], Message: Normalize(m[3]), Example: example(e.Message)}, true
}

// priorityLevel maps the syslog PRIORITY: 0-3 error, 4 warning, 7 debug, the rest info.
func priorityLevel(priority string) string {
	n, err := strconv.Atoi(priority)
	switch {
	case err != nil:
		return LevelInfo
	case n <= 3:
		return LevelError
	case n == 4:
		return LevelWarn
	case n == 7:
		return LevelDebug
	}
	return LevelInfo
}

// unitService names a line by its systemd unit, or its process when it has none.
func unitService(e Entry) string {
	switch {
	case e.Comm == "systemd":
		return "systemd"
	case strings.HasPrefix(e.Unit, "terrascale-orchestrator"):
		return "ts-orchestrator"
	case e.Unit != "":
		return strings.TrimSuffix(e.Unit, ".service")
	}
	return commService(e)
}

// commService names a line by its process.
func commService(e Entry) string {
	switch {
	case strings.HasPrefix(e.Comm, "terrascale-orch"):
		return "ts-orchestrator"
	case e.Comm == "":
		return "unknown"
	}
	return e.Comm
}

	uuid    = regexp.MustCompile(`[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}`)
	ulid    = regexp.MustCompile(`\b[0-7][0-9A-HJKMNP-TV-Z]{25}\b`)
	address = regexp.MustCompile(`\b\d{1,3}(\.\d{1,3}){3}(:\d+)?\b`)
	number  = regexp.MustCompile(`\b[0-9a-fA-F]*[0-9][0-9a-fA-F]*\b|\d+`)
)

// Normalize turns a message into its class: credentials are redacted, then
// identifiers, addresses and numbers become N, so one cause counts as one class.
func Normalize(message string) string {
	// The whole message is redacted before the cut: a cut first could leave half a credential.
	s := strings.TrimSpace(observability.RedactText(message, len(message)))
	for _, pattern := range []*regexp.Regexp{uuid, ulid, address, number} {
		s = pattern.ReplaceAllString(s, "N")
	}
	return cut(s, 160)
}

// example is the raw message a class keeps once, with its credentials redacted.
func example(message string) string {
	return observability.RedactText(strings.TrimSpace(message), 512)
}

// cut keeps at most n bytes of s without splitting a UTF-8 sequence.
func cut(s string, n int) string {
	if len(s) <= n {
		return s
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n--
	}
	return s[:n]
}

func sensitiveLogKey(key string) bool {
	if len(key) > maxLogScanBytes {
		return true
	}
	var normalized strings.Builder
	for _, r := range key {
		if r >= 'A' && r <= 'Z' {
			r += 'a' - 'A'
		}
		if r >= 'a' && r <= 'z' || r >= '0' && r <= '9' {
			normalized.WriteRune(r)
		}
	}
	name := normalized.String()
	for _, sensitive := range []string{"authorization", "cookie", "session", "password", "passwd", "token", "secret", "seed", "privatekey", "credential", "accesskey", "apikey"} {
		if strings.Contains(name, sensitive) {
			return true
		}
	}
	return false
}

var (
	logPEM    = regexp.MustCompile(`(?s)-----BEGIN [A-Z0-9 ]+-----.*?(?:-----END [A-Z0-9 ]+-----|$)`)
	logBearer = regexp.MustCompile(`(?i)\bbearer\s+[^\s"'<>;,]+`)
	logJWT    = regexp.MustCompile(`\b[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]*`)
	logSeed   = regexp.MustCompile(`\bS[A-Z2-7]{57,}`)
	logURL    = regexp.MustCompile(`[A-Za-z][A-Za-z0-9+.-]*://[^\s"'<>]+`)
	logQuery  = regexp.MustCompile(`[?&#][^&\s#"'<>]+=[^&\s#"'<>]*`)
)

func (s *logSanitizer) text(value string, limit int) string {
	// Fail closed rather than cutting an unfinished credential at the scan
	// boundary. All regex work is RE2 and limited to this input size.
	if len(value) > maxLogScanBytes {
		s.truncated = true
		return omittedLogValue
	}
	if !utf8.ValidString(value) {
		s.truncated = true
		value = strings.ToValidUTF8(value, "�")
	}
	value = logPEM.ReplaceAllString(value, redactedLogValue)
	value = logURL.ReplaceAllStringFunc(value, func(raw string) string {
		parsed, err := url.Parse(raw)
		if err != nil {
			return redactedLogValue
		}
		if parsed.User != nil {
			parsed.User = url.User(redactedLogValue)
		}
		return parsed.String()
	})
	value = logQuery.ReplaceAllStringFunc(value, func(raw string) string {
		key, _, _ := strings.Cut(raw[1:], "=")
		decoded, err := url.QueryUnescape(key)
		if err != nil || sensitiveLogKey(decoded) {
			return raw[:1] + key + "=" + redactedLogValue
		}
		return raw
	})
	value = logBearer.ReplaceAllString(value, "Bearer "+redactedLogValue)
	value = logJWT.ReplaceAllStringFunc(value, func(raw string) string {
		header, _, _ := strings.Cut(raw, ".")
		decoded, err := base64.RawURLEncoding.DecodeString(header)
		if err == nil && strings.HasPrefix(strings.TrimSpace(string(decoded)), "{") && json.Valid(decoded) {
			return redactedLogValue
		}
		return raw
	})
	value = logSeed.ReplaceAllString(value, redactedLogValue)
	if len(value) > limit {
		s.truncated = true
		cut := limit - len("...")
		for cut > 0 && !utf8.RuneStart(value[cut]) {
			cut--
		}
		value = value[:cut] + "..."
	}
	// Clone even short substrings: scoped strings must not pin large input buffers.
	return strings.Clone(value)
}

// RedactText applies the structured logger's credential redaction to value and
// keeps at most limit bytes. Text too large to scan becomes "[truncated]".
func RedactText(value string, limit int) string {
	s := logSanitizer{}
	return s.text(value, limit)
}

func logscanProcess(ctx context.Context, env []string, name string, args ...string) ([]byte, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.Env = append(os.Environ(), "LC_ALL=C")
	cmd.Env = append(cmd.Env, env...)
	cmd.WaitDelay = time.Second
	out, err := cmd.CombinedOutput()
	if err != nil {
		err = fmt.Errorf("%w: %s", err, bytes.TrimSpace(out))
	}
	return out, err
}

func logscanFiles(t *testing.T) (Fetchers, string) {
	t.Helper()
	dir := t.TempDir()
	for name, content := range map[string]string{
		"gru-1-ctl-1":  journal,
		"gru-1-ctl-2":  "",
		"ts-dashboard": fly,
		"journalctl": `#!/bin/sh
printf '%s\n' "$@" > "$LOGSCAN_FIXTURES/journal-args"
exec cat "$LOGSCAN_FIXTURES/$LOGSCAN_NODE"
`,
		"fly": `#!/bin/sh
[ "$#" -eq 4 ] && [ "$1" = logs ] && [ "$2" = -a ] && [ "$4" = --no-tail ] || exit 2
exec cat "$LOGSCAN_FIXTURES/$3"
`,
	} {
		mode := os.FileMode(0o600)
		if name == "journalctl" || name == "fly" {
			mode = 0o700
		}
		if err := os.WriteFile(filepath.Join(dir, name), []byte(content), mode); err != nil {
			t.Fatal(err)
		}
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("LOGSCAN_FIXTURES", dir)
	return Fetchers{
		Node: func(ctx context.Context, node, command string) ([]byte, error) {
			return logscanProcess(ctx, []string{"LOGSCAN_NODE=" + node}, "bash", "-c", command)
		},
		Fly: func(ctx context.Context, app string) ([]byte, error) {
			return logscanProcess(ctx, nil, "fly", "logs", "-a", app, "--no-tail")
		},
	}, dir
}

