// levelPattern matches, in journalctl's JSON, a .NET console record's first
// line, a slog JSON record and an embedded NATS server line at warning or
// above.
const levelPattern = `"MESSAGE":"(warn|fail|crit): |\\"level\\":\\"(WARN|ERROR)\\"|"MESSAGE":"\[[0-9]+\] \[(WRN|ERR|FTL)\] `

// RemoteCommand prints the orchestrator units' journal records of the last
// since that match levelPattern, each with the two records after it: a .NET
// record's message is the line after its level. No match is not an error.
func RemoteCommand(since time.Duration) string {
	return fmt.Sprintf(`set -o pipefail; journalctl --since -%ds --no-pager -o json --output-fields=_COMM,_PID,MESSAGE -u "terrascale-orchestrator*" | { grep -a -A2 -E '%s' || [ $? -eq 1 ]; }`,
		int(since.Seconds()), levelPattern)
}

// ParseJournal reads RemoteCommand's output: the WARN and ERROR records among
// the lines it matched, classified by internal/logs.
func ParseJournal(out []byte) []Record {
	var parser logs.Parser
	var records []Record
	add := func(r logs.Record, ok bool) {
		if ok && warning(r.Level) {
			records = append(records, Record{r.Service, r.Level, class(r)})
		}
	}
	for line := range bytes.Lines(out) {
		if e, ok := logs.DecodeJournal(line); ok { // grep's "--" separators are not records
			add(parser.Parse(e))
		}
	}
	for _, r := range parser.Flush() {
		add(r, true)
	}
	return records
}

func warning(level string) bool {
	return level == logs.LevelWarn || level == logs.LevelError
}

// class is the record's class text: the component, then the message.
func class(r logs.Record) string {
	if r.Component == "" {
		return r.Message
	}
	return r.Component + ": " + r.Message
}

var (
	ansi      = regexp.MustCompile(`\x1b\[[0-9;]*m`)
	flyLine   = regexp.MustCompile(`^(\S+Z) (\S+) \S+ \[(\w+)\]\s*(.*)$`)
	slogLevel = regexp.MustCompile(`\blevel=(WARN|ERROR) msg=("(?:[^"\\]|\\.)*"|\S+)(?:.*?\berror=("(?:[^"\\]|\\.)*"|\S+))?`)
)

// ParseFly reads "fly logs --no-tail" output, keeping lines from after.
func ParseFly(app string, out []byte, after time.Time) []Record {
	var records []Record
	for line := range strings.Lines(ansi.ReplaceAllString(string(out), "")) {
		m := flyLine.FindStringSubmatch(strings.TrimSpace(line))
		if m == nil {
			continue
		}
		at, err := time.Parse(time.RFC3339, m[1])
		if err != nil || at.Before(after) {
			continue
		}
		if r, ok := logs.Classify(logs.Entry{Comm: app, Message: m[4]}); ok && warning(r.Level) {
			records = append(records, Record{app, r.Level, class(r)})
			continue
		}
		s := slogLevel.FindStringSubmatch(m[4])
		if s == nil {
			// Fly's proxy and runner tag their own lines warn or error.
			if level := strings.ToUpper(m[3]); level == "WARN" || level == "ERROR" {
				source, _, _ := strings.Cut(m[2], "[")
				records = append(records, Record{app, level, source + ": " + logs.Normalize(m[4])})
			}
			continue
		}
		class := strings.Trim(s[2], `"`)
		if s[3] != "" {
			class += ": " + strings.Trim(s[3], `"`)
		}
		records = append(records, Record{app, s[1], logs.Normalize(class)})
	}
	return records
}

func DecodeJournal(line []byte) (Entry, bool) {
	var raw struct {
		Unit     string          `json:"_SYSTEMD_UNIT"`
		Comm     string          `json:"_COMM"`
		PID      string          `json:"_PID"`
		Priority string          `json:"PRIORITY"`
		Realtime string          `json:"__REALTIME_TIMESTAMP"`
		Message  json.RawMessage `json:"MESSAGE"`
	}
	if json.Unmarshal(line, &raw) != nil {
		return Entry{}, false
	}
	var message string
	if json.Unmarshal(raw.Message, &message) != nil {
		return Entry{}, false
	}
	entry := Entry{Unit: raw.Unit, Comm: raw.Comm, PID: raw.PID, Message: message, Priority: raw.Priority}
	if micros, err := strconv.ParseInt(raw.Realtime, 10, 64); err == nil {
		entry.At = time.UnixMicro(micros)
	}
	return entry, true
}

func validLevel(level string) bool {
	return severity(level) >= 0
}

func severity(level string) int {
	for i, known := range levels {
		if known == level {
			return i
		}
	}
	return -1
}

func (p *Parser) Parse(e Entry) (Record, bool) {
	p.queue = append(p.queue, p.step(e)...)
	if len(p.queue) == 0 {
		return Record{}, false
	}
	r := p.queue[0]
	p.queue = p.queue[1:]
	return r, true
}

// Flush returns the queued records and the headers whose message never came.
func (p *Parser) Flush() []Record {
	out := p.queue
	p.queue = nil
	for pid, head := range p.held {
		out = append(out, head)
		delete(p.held, pid)
	}
	return out
}

func (p *Parser) step(e Entry) []Record {
	var out []Record
	indented := strings.HasPrefix(e.Message, " ")
	if head, ok := p.held[e.PID]; ok {
		delete(p.held, e.PID)
		if indented {
			if p.inRecord == nil {
				p.inRecord = make(map[string]bool)
			}
			p.inRecord[e.PID] = true
			head.Message, head.Example = Normalize(e.Message), example(e.Message)
			return []Record{head}
		}
		out = append(out, head)
	}
	// Exception text and stack frames are indented too; they end with the record.
	if indented && p.inRecord[e.PID] {
		return out
	}
	delete(p.inRecord, e.PID)
	if head, ok := dotnetHeader(e); ok {
		if p.held == nil {
			p.held = make(map[string]Record)
		}
		p.held[e.PID] = head
		return out
	}
	if r, ok := Classify(e); ok {
		out = append(out, r)
	}
	return out
}

// Classify classifies an entry that is a whole record by itself. Any other
// line is a record too, at the level its journal PRIORITY gives.
func Classify(e Entry) (Record, bool) {
	if strings.TrimSpace(e.Message) == "" {
		return Record{}, false
	}
	for _, classify := range []func(Entry) (Record, bool){slogRecord, natsRecord, netbirdRecord} {
		if r, ok := classify(e); ok {
			return r, true
		}
	}
	return Record{Service: unitService(e), Level: priorityLevel(e.Priority), Message: Normalize(e.Message), Example: example(e.Message)}, true
}

// slogRecord reads record v1 and slog JSON: {"level","msg","component","error","service"}.
func slogRecord(e Entry) (Record, bool) {
	var slog struct {
		Level     string `json:"level"`
		Msg       string `json:"msg"`
		Component string `json:"component"`
		Error     string `json:"error"`
		Service   string `json:"service"`
	}
	if !strings.HasPrefix(e.Message, "{") || json.Unmarshal([]byte(e.Message), &slog) != nil || !validLevel(slog.Level) {
		return Record{}, false
	}
	message := slog.Msg
	if slog.Error != "" {
		message += ": " + slog.Error
	}
	return Record{Service: cmp.Or(slog.Service, unitService(e)), Level: slog.Level, Component: slog.Component,
		Message: Normalize(message), Example: example(e.Message)}, true
}

var (
	dotnetHeaderLine = regexp.MustCompile(`^(trce|dbug|info|warn|fail|crit): ([^\[ ]+)`)
	dotnetLevels     = map[string]string{"trce": LevelDebug, "dbug": LevelDebug, "info": LevelInfo, "warn": LevelWarn, "fail": LevelError, "crit": LevelError}
)

// dotnetHeader reads a .NET console header; its message follows on a later line.
func dotnetHeader(e Entry) (Record, bool) {
	m := dotnetHeaderLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	return Record{Service: commService(e), Level: dotnetLevels[m[1]], Component: m[2]}, true
}

var (
	natsLine   = regexp.MustCompile(`^\[\d+\] \[(INF|WRN|ERR|FTL|DBG|TRC)\] (.*)`)
	natsLevels = map[string]string{"TRC": LevelDebug, "DBG": LevelDebug, "INF": LevelInfo, "WRN": LevelWarn, "ERR": LevelError, "FTL": LevelError}
	// A permission violation names its client and account; one cause is one class.
	violationQuote   = regexp.MustCompile(`"[^"]*"`)
	violationAccount = regexp.MustCompile(`\b(account|JWT)\s+\S+`)
)

// natsRecord reads an embedded NATS server line: "[pid] [WRN] text".
func natsRecord(e Entry) (Record, bool) {
	m := natsLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	text := m[2]
	if strings.Contains(text, "Violation") {
		text = violationAccount.ReplaceAllString(violationQuote.ReplaceAllString(text, ""), "")
	}
	return Record{Service: "ts-orchestrator", Level: natsLevels[m[1]], Component: "nats", Message: Normalize(text), Example: example(e.Message)}, true
}

var (
	netbirdLine   = regexp.MustCompile(`^\S+ (TRAC|DEBU|INFO|WARN|ERRO|FATA|PANI) (?:\[[^\]]*\] )?(\S+?):\d+: (.*)$`)
	netbirdLevels = map[string]string{"TRAC": LevelDebug, "DEBU": LevelDebug, "INFO": LevelInfo, "WARN": LevelWarn, "ERRO": LevelError, "FATA": LevelError, "PANI": LevelError}
)

// netbirdRecord reads a NetBird client line: "time LEVEL [peer] file.go:line: text".
func netbirdRecord(e Entry) (Record, bool) {
	m := netbirdLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	return Record{Service: "netbird", Level: netbirdLevels[m[1]], Component: m[2], Message: Normalize(m[3]), Example: example(e.Message)}, true
}

// priorityLevel maps the syslog PRIORITY: 0-3 error, 4 warning, 7 debug, the rest info.
func priorityLevel(priority string) string {
	n, err := strconv.Atoi(priority)
	switch {
	case err != nil:
		return LevelInfo
	case n <= 3:
		return LevelError
	case n == 4:
		return LevelWarn
	case n == 7:
		return LevelDebug
	}
	return LevelInfo
}

// unitService names a line by its systemd unit, or its process when it has none.
func unitService(e Entry) string {
	switch {
	case e.Comm == "systemd":
		return "systemd"
	case strings.HasPrefix(e.Unit, "terrascale-orchestrator"):
		return "ts-orchestrator"
	case e.Unit != "":
		return strings.TrimSuffix(e.Unit, ".service")
	}
	return commService(e)
}

