// entries is ordered: placement assigns permanent members in this order.
var entries = [...]Entry{
	{Cell: GRU, OCIRegion: "sa-saopaulo-1", OCIRegionKey: "GRU", City: "São Paulo", Country: "BR", Latitude: -23.43, Longitude: -46.47},
	{Cell: SFO, OCIRegion: "us-sanjose-1", OCIRegionKey: "SJC", City: "San Jose", Country: "US", Latitude: 37.34, Longitude: -121.89},
	{Cell: FRA, OCIRegion: "eu-frankfurt-1", OCIRegionKey: "FRA", City: "Frankfurt", Country: "DE", Latitude: 50.11, Longitude: 8.68},

func Lookup(cell string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Cell == cell {
			return entry, true
		}
	}
	return Entry{}, false
}

// IsCell reports whether cell is an exact upper-case supported cell code.
func IsCell(cell string) bool {
	_, ok := Lookup(cell)
	return ok
}

// Servers are the peers named like a cell's node or server, sorted.
func Servers(peers map[string]string) []string {
	var servers []string
	for name := range peers {
		// A cell name (gru-1) is valid too but names no server.
		if !strings.Contains(name, ".") && strings.Count(name, "-") > 1 && naming.Validate(name) == nil {
			servers = append(servers, name)
		}
	}
	slices.Sort(servers)
	return servers
}

func Regional(cell string, tokens ...string) string {
	root, err := RegionalRoot(cell)
	if err != nil {
		return ""
	}
	return joinSubject(root, tokens)
}

func AgentObservation(cell, agent, observation string) string {
	return Regional(cell, "agent", agent, "observation", observation)
}

func joinSubject(root string, tokens []string) string {
	if len(tokens) == 0 {
		return root
	}
	var builder strings.Builder
	builder.WriteString(root)
	for index, token := range tokens {
		for part := range strings.SplitSeq(token, ".") {
			if !validFamilyToken(part, index == len(tokens)-1) {
				return ""
			}
		}
		builder.WriteByte('.')
		builder.WriteString(token)
	}
	result := builder.String()
	// ">" may only terminate the whole subject.
	if index := strings.Index(result, ">"); index >= 0 && index != len(result)-1 {
		return ""
	}
	return result
}

func validFamilyToken(token string, last bool) bool {
	switch token {
	case "*", TemplateSubject:
		return true
	case ">":
		return last
	}
	if token == "" || len(token) > 128 {
		return false
	}
	for _, character := range token {
		switch {
		case character >= 'a' && character <= 'z', character >= 'A' && character <= 'Z',
			character >= '0' && character <= '9', character == '-', character == '_':
		default:
			return false
		}
	}
	return true
}

func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}
